import{_ as s,a0 as p,w as r,s as i,I as n,x as e,a1 as a,A as l,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"为何 Elementary OS 中使用 Pantheon 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"为何 Elementary OS 中使用 Pantheon 桌面 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为何 Elementary OS 中使用 Pantheon 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为何 Elementary OS 中使用 Pantheon 桌面 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191203 Why use the Pantheon desktop for Linux Elementary OS","title":"为何 Elementary OS 中使用 Pantheon 桌面","tag":"201912","desc":""},"relativePath":"201912/20191203 Why use the Pantheon desktop for Linux Elementary OS.md","filePath":"[post].md"}'),h={name:"201912/20191203 Why use the Pantheon desktop for Linux Elementary OS.md"};function m(d,t,f,P,g,x){const o=p("Link");return r(),i("div",null,[t[23]||(t[23]=n("h1",{id:"为何-elementary-os-中使用-pantheon-桌面",tabindex:"-1"},[e("为何 Elementary OS 中使用 Pantheon 桌面 "),n("a",{class:"header-anchor",href:"#为何-elementary-os-中使用-pantheon-桌面","aria-label":"Permalink to “为何 Elementary OS 中使用 Pantheon 桌面”"},"​")],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,"本文是 Linux 桌面特别系列的一部分。通过在 Elementary OS 上运行 Pantheon 桌面获得广受喜爱的 Mac OS 特性。")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/10/085342dfgngrpt6sgzl3af.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=e("你愿意为 Linux 桌面支付 20 美元吗？事实上，我会在下载自由软件时选择支付更多的钱！我这样做的原因是开源是值得的。对于 ",-1)),a(o,{href:"https://elementary.io/"},{default:l(()=>[...t[0]||(t[0]=[e("Elementary OS",-1)])]),_:1}),t[2]||(t[2]=e(" 的拷贝，默认价格是 20 美元（你可以选择 1 美元，如果你无法负担，你甚至可以用 0 美元下载）。作为回报，你将获得一个出色且精心制作的发行版，同时拥有它自己的 Pantheon 桌面设计。",-1))]),n("p",null,[t[5]||(t[5]=e("你可能会发现 Pantheon 已包含在软件仓库中，因为它是开源的，但你更可能需要下载并安装 ",-1)),a(o,{href:"http://elementary.io"},{default:l(()=>[...t[3]||(t[3]=[e("Elementary",-1)])]),_:1}),t[6]||(t[6]=e(" Linux 才能体验它。如果你还不准备在计算机上将 Elementary 作为主操作系统，那么可以将其安装到虚拟机中，例如 ",-1)),a(o,{href:"https://opensource.com/article/19/5/getting-started-gnome-boxes-virtualization"},{default:l(()=>[...t[4]||(t[4]=[e("GNOME Boxes",-1)])]),_:1}),t[7]||(t[7]=e(" 中。",-1))]),t[26]||(t[26]=u('<p>Pantheon 桌面整洁、吸引人，并且有许多用户希望在桌面中获得的东西，但在普通的 Linux 桌面上却无法获得。</p><h3 id="pantheon-桌面之旅" tabindex="-1">Pantheon 桌面之旅 <a class="header-anchor" href="#pantheon-桌面之旅" aria-label="Permalink to “Pantheon 桌面之旅”">​</a></h3><p>乍一看，Pantheon 桌面看起来有点像 Cinnamon、Budgie 或 GNOME 3 的经典模式。但是，Pantheon 最令人兴奋的功能是极小的接触。它在你很少注意到的地方都表现出色，直到有一天这里成为了你一天都会看的地方，并且会意识到它的工作方式确实改善了你的生活质量，更不用说让你过得愉快多了。</p><p>最明显的例子是“文件名高亮”。几十年来，Mac OS 一直有一个广受欢迎的功能，你可以高亮显示重要文件的名称。人们使用此功能作为快速视觉指示器，来告诉自己哪个文件是这几个的“最佳”版本，或者哪个文件应该发送给朋友，或者哪个文件仍然需要处理。它们可以是任意颜色，可以表示用户想要的任何含义。最重要的是，它是引人注目的视觉元数据。</p><p>从 Mac OS 切换过来用户往往会在 GNOME 和 KDE 以及 Linux 提供的其它桌面里怀念这个功能。Pantheon 悄悄地随手解决了这个问题。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-pantheon-highlight.jpg" alt="A highlighted file in the Pantheon desktop" title="A highlighted file in the Pantheon desktop"></p><p>当然，那只是其中一个例子。Pantheon 有很多你直到用才会想到的小功能。</p><p>桌面精致而吸引人，有所有其他很多桌面缺少的直观组件。在许多方面，它充分吸取了其他桌面好的想法，并避免实现多余的东西。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-pantheon.jpg" alt="Pantheon desktop on Elementary OS" title="Pantheon desktop on Elementary OS"></p><h3 id="自定义-pantheon-桌面" tabindex="-1">自定义 Pantheon 桌面 <a class="header-anchor" href="#自定义-pantheon-桌面" aria-label="Permalink to “自定义 Pantheon 桌面”">​</a></h3><p>Pantheon 桌面表达了如何操作计算机的清晰愿景。这种设计的“问题”（至少在开源之外）是，一个人的偏好可能无法满足另一个人的效率。</p><p>但它是开源的。它可以更改，任何不能改变的东西都可以被丢弃。Pantheon 绝对是针对特定用户群的桌面，但是即使对于那些对桌面应该如何工作抱有自己期望的人，Pantheon 也会比初看上去更加灵活。许多内置设计都具有替代选项，当你无法根据自己的喜好进行调整时，你可以轻松选择其他应用。主题引擎可确保你的替换应用看起来与桌面的其它部分和谐一致，而通常的 Linux 系统兼容性可确保你选择的所有应用都能按预期相互配合。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-pantheon-pcmanfm.jpg" alt="Which one is the guest?" title="Which one is the guest?"></p><p>这些替代品，可使你事半功倍。</p><h3 id="受欢迎的补充" tabindex="-1">受欢迎的补充 <a class="header-anchor" href="#受欢迎的补充" aria-label="Permalink to “受欢迎的补充”">​</a></h3><p>撇开这个桌面的词源不说，此桌面确实是许多 Linux 用户祈祷的答案（LCTT 译注：Pantheon 的意思是“万神庙”）。无论它是否是你的风格，Pantheon 桌面都是 Linux 用户体验中重要且受欢迎的补充。自己尝试一下，看看它是否是你一直期待的。</p><hr>',17)),n("p",null,[t[9]||(t[9]=e("via: ",-1)),a(o,{href:"https://opensource.com/article/19/12/pantheon-linux-desktop"},{default:l(()=>[...t[8]||(t[8]=[e("https://opensource.com/article/19/12/pantheon-linux-desktop",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("作者：",-1)),a(o,{href:"https://opensource.com/users/seth"},{default:l(()=>[...t[10]||(t[10]=[e("Seth Kenlon",-1)])]),_:1}),t[15]||(t[15]=e(" 选题：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 译者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:l(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原创编译，",-1)),a(o,{href:"https://linux.cn/"},{default:l(()=>[...t[19]||(t[19]=[e("Linux中国",-1)])]),_:1}),t[22]||(t[22]=e(" 荣誉推出",-1))])])}const E=s(h,[["render",m]]);export{S as __pageData,E as default};
